        largestSubstring = Math.max(largestSubstring, substring.length());
      }
    }
  }
  return largestSubstring;
}

public int findLargestSubstring(List<String> strings) {
  int largestSubstring = 0;
  for (String str : strings) {
    String inverse = new StringBuilder(str).reverse().toString();
    for (String otherStr : strings) {
      if (str.contains(inverse) || otherStr.contains(inverse)) {
        largestSubstring = Math.max(largestSubstring, str.length());
        break;
      }
    }
  }
  return largestSubstring;
}

