    for (int i = 0; i < hasApple.length; i++) {
        if (hasApple[i]) {
            int parent = find(i, parents);
            minTime = Math.max(minTime, Math.abs(parent - i));
        }
    }

    return minTime;
}

private int find(int node, int[] parents) {
    if (parents[node] == node) {
        return node;
    }
    return find(parents[node], parents);
