public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Dijkstra's algorithm to find the shortest path from node 0 to all other nodes
    int[] distance = new int[n];
    Arrays.fill(distance, Integer.MAX_VALUE);
    distance[0] = 0;

    PriorityQueue<int[]> queue = new PriorityQueue<>((a, b) -> a[1] - b[1]);
    queue.add(new int[] { 0, 0 });

    while (!queue.isEmpty()) {
        int[] curr = queue.poll();
        int node = curr[0];
        int dist = curr[1];

        if (dist < distance[node]) {
            distance[node] = dist;

            for (int i = 0; i < edges.length; i++) {
                if (edges[i][0] == node && hasApple[edges[i][1]]) {
                    int newDist = dist + 1;
                    if (newDist < distance[edges[i][1]]) {
                        distance[edges[i][1]] = newDist;
                        queue.add(new int[] { edges[i][1], newDist });
                    }
                }
            }
        }
    }

    // Return the total time required to collect all the apples and return to node 0
    int totalTime = 0;
    for (int i = 1; i < n; i++) {
        if (hasApple[i]) {
            totalTime += distance[i];
        }
    }
    return totalTime;
}
