    while (!isSorted(permutations)) {
        int max = Integer.MIN_VALUE;
        int maxIndex = 0;
        for (int i = 0; i < n; i++) {
            if (permutations[i] > max) {
                max = permutations[i];
                maxIndex = i;
            }
        }
        swap(permutations, maxIndex, maxIndex - 1);
        count++;
    }
    return count;
}

private static boolean isSorted(int[] permutations) {
    for (int i = 0; i < permutations.length - 1; i++) {
        if (permutations[i] > permutations[i + 1]) {
            return false;
        }
    }
    return true;
}

